package com.termux.app.workspace;
import java.util.*;import java.nio.charset.StandardCharsets;import java.io.*;
/** Git reads only; no optional index locks, external diff, textconv, hooks or network operations. */
final class ProjectChanges {
 interface Reader{byte[] read(String script,int max)throws Exception;}
 static final String GIT="jobs_git";
 static final String SAFE="export GIT_OPTIONAL_LOCKS=0 GIT_TERMINAL_PROMPT=0; set -f; jobs_git(){ for jobs_key in $(command git config --name-only --get-regexp '^filter[.].*[.](clean|smudge|process|required)$'); do case \"$jobs_key\" in *[!a-zA-Z0-9._-]*) return 125;; esac; case \"$jobs_key\" in *.clean|*.smudge) set -- -c \"$jobs_key=\" \"$@\";; *.process) set -- -c \"$jobs_key=\" \"$@\";; *.required) set -- -c \"$jobs_key=false\" \"$@\";; esac; done; command git --no-optional-locks --no-pager --literal-pathspecs -c core.fsmonitor=false -c core.untrackedCache=false \"$@\"; }; ";
 static final class Entry{final String path,code;String original="";Entry(String p,String c){path=p;code=c;}}
 static final class Listing{String root="",head="",state="";final List<Entry> entries=new ArrayList<>();}
 static String listScript(String dir){return SAFE+"command -v git >/dev/null 2>&1 || { printf 'NO_GIT\\0'; exit 0; }; cd -- "+ProjectFiles.target(dir)+" || exit 2; root=$("+GIT+" rev-parse --show-toplevel 2>/dev/null) || { printf 'NO_PROJECT\\0'; exit 0; }; cd -- \"$root\" || exit 2; head=$("+GIT+" rev-parse --verify HEAD 2>/dev/null) || { printf 'NO_HEAD\\0%s\\0' \"$root\"; exit 0; }; printf 'OK\\0%s\\0%s\\0' \"$root\" \"$head\"; "+GIT+" status --porcelain=v1 -z --untracked-files=all";}
 static Listing parse(byte[] raw)throws IOException{String[] p=new String(raw,StandardCharsets.UTF_8).split("\0",-1);Listing r=new Listing();r.state=p[0];if(!r.state.equals("OK")){if(p.length>1)r.root=p[1];return r;}if(p.length<4)throw new IOException("INVALID_GIT_STATUS");r.root=p[1];r.head=p[2];for(int i=3;i<p.length&&!p[i].isEmpty();i++){String v=p[i];if(v.length()<4||v.charAt(2)!=' ')throw new IOException("INVALID_GIT_STATUS");String c=v.substring(0,2),path=v.substring(3);Entry entry=new Entry(path,c);r.entries.add(entry);if(c.indexOf('R')>=0||c.indexOf('C')>=0){if(++i>=p.length)throw new IOException("INVALID_RENAME");entry.original=p[i];}}return r;}
 static String diffScript(Listing l,Entry e){String f=SessionShell.quote(e.path)+(e.original.isEmpty()?"":" "+SessionShell.quote(e.original));String diff=GIT+" diff --no-ext-diff --no-textconv --no-renames";String range=e.code.equals("??")?"--no-index -- /dev/null "+f:l.head+" -- "+f;return SAFE+"cd -- "+ProjectFiles.target(l.root)+" || exit 2; "+(e.code.equals("??")?"test -e "+f+" || test -L "+f+" || exit 2; ":"")+"n=$("+diff+" --numstat "+range+"); jobs_result=$?; [ \"$jobs_result\" -le 1 ] || exit 2; case \"$n\" in -*) printf 'BINARY\\n'; exit 0;; esac; printf 'TEXT\\n'; "+diff+" --no-color --unified=3 "+range+"; result=$?; [ \"$result\" -le 1 ]";}
 static Listing list(Reader r,String dir)throws Exception{return parse(r.read(listScript(dir),ProjectFiles.MAX_LIST));}
 static String diff(Reader r,Listing l,Entry e)throws Exception{return new String(r.read(diffScript(l,e),ProjectFiles.MAX_PREVIEW),StandardCharsets.UTF_8);}
}
